// Normalize Data Engineering alert from Databricks, PostgreSQL/pgvector, dbt, or n8n Error Trigger
const crypto = require('crypto');
const raw = $input.first().json;
const body = raw.body || raw;

const incidentId = 'DE-INC-' + Date.now() + '-' + Math.random().toString(36).substring(2, 6).toUpperCase();
const pipelineName = body.pipeline_name || body.job_name || raw.workflow?.name || 'databricks_delta_silver_etl';
const sourceSystem = body.source_system || 'Databricks Delta / PostgreSQL pgvector';
const failureType = body.failure_type || body.error_code || 'SCHEMA_DRIFT_DETECTED';
const errorMessage = body.error_message || raw.execution?.error?.message || 'Column type mismatch on payload_timestamp; 14,200 rows held in Dead-Letter Queue.';
const affectedTable = body.affected_table || 'silver.client_telemetry_events';
const downstreamConsumers = body.downstream_consumers || 'gold.executive_kpis, pgvector.rag_knowledge_index';
const dlqRowCount = Number(body.dlq_row_count || 14200);
const databricksJobId = body.databricks_job_id || '8492014';
const stewardName = body.steward_name || 'Ismyl Mohammad';
const stewardPhone = body.steward_phone || '+918360193921';
const severity = body.severity || (dlqRowCount > 1000 ? 'CRITICAL' : 'HIGH');

const sha256AlertDigest = crypto.createHash('sha256').update(JSON.stringify({
  incidentId, pipelineName, affectedTable, failureType, errorMessage, ts: new Date().toISOString()
})).digest('hex');

return [{
  json: {
    incident_id: incidentId,
    pipeline_name: pipelineName,
    source_system: sourceSystem,
    failure_type: failureType,
    error_message: errorMessage,
    affected_table: affectedTable,
    downstream_consumers: downstreamConsumers,
    dlq_row_count: dlqRowCount,
    databricks_job_id: databricksJobId,
    steward_name: stewardName,
    steward_phone: stewardPhone,
    severity: severity,
    sha256_alert_digest: sha256AlertDigest,
    created_at_iso: new Date().toISOString()
  }
}];

