const body = $input.first().json.body || $input.first().json;
const message = body.message || {};
const toolCall = (message.toolCalls && message.toolCalls[0]) || (message.toolWithToolCallList && message.toolWithToolCallList[0]?.toolCall) || {};
const fnName = toolCall.function?.name || 'query_pipeline_health_and_lineage';
let args = toolCall.function?.arguments || {};
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch (e) { args = {}; }
}
return [{
  json: {
    tool_call_id: toolCall.id || 'call_de_tool',
    function_name: fnName,
    arguments: args
  }
}];

