const crypto = require('crypto');
const body = $input.first().json.body || $input.first().json;
const msg = body.message || body;
const call = msg.call || {};
const vars = call.assistantOverrides?.variableValues || {};
const analysis = msg.analysis || {};

const incidentId = vars.incident_id || 'DE-INC-MANUAL';
const pipelineName = vars.pipeline_name || 'databricks_delta_silver_etl';
const affectedTable = vars.affected_table || 'silver.client_telemetry_events';
const transcript = msg.transcript || '';
const summary = analysis.summary || msg.summary || 'Voice incident remediation completed.';
const recordingUrl = msg.recordingUrl || call.recordingUrl || '';

const sha256DecisionHash = crypto.createHash('sha256').update(JSON.stringify({
  incidentId, pipelineName, transcript, timestamp: new Date().toISOString()
})).digest('hex');

return [{
  json: {
    incident_id: incidentId,
    pipeline_name: pipelineName,
    affected_table: affectedTable,
    summary: summary,
    transcript: transcript,
    recording_url: recordingUrl,
    sha256_decision_hash: sha256DecisionHash
  }
}];
